def read_sensors(device_id: str | None = None) -> dict:
    """每个工具都返回 {ok, text, data}，上层不需要关心是谁调的。"""
    if device_id:
        d = sensors.get(device_id)
        level, reasons = sensors.level_of(d)
        d["level"], d["reasons"] = level, reasons
        return {"ok": True, "text": "%s 读数已取回" % d["name"], "data": [d]}

REGISTRY = {
    "read_sensors":      {"desc": "读取温湿度与可燃气体", "run": read_sensors},
    "retrieve_knowledge": {"desc": "检索运维知识库",      "run": retrieve_knowledge},
    "create_ticket":      {"desc": "生成运维工单",        "run": create_ticket},
}

